      "type": "number",
      "title": "Detection threshold",
      "description": "The probability Jev must give a use case for a command to count as a sandbox job",
      "default": 0.5
    },
    "judgeTimeoutMs": {
      "type": "number",
      "title": "Jev latency budget (ms)",
