    }
    if (sub === '' || sub === 'start' || sub === 'open') {
      await openPane()
      if (!credentials) return { text: `jev-vercel-sandbox: not configured, set ${missing.join(', ')} in the plugin's options` }
      if (sub !== 'open' && state !== 'ready' && state !== 'starting') {
