    const width = Math.max(20, e.props.bodyColumns - 1)
    const fit = (s: string, w = width) => (s.length > w ? `${s.slice(0, Math.max(1, w - 1))}…` : s)
    const noop = () => {}
    const left = minutesLeft()

    const badge =
      state === 'ready' ? (
        <Text color="green" bold>● ready</Text>
      ) : state === 'starting' ? (
        <Text color="yellow" bold>◌ loading the sandbox…</Text>
      ) : state === 'failed' ? (
        <Text color="red" bold>✗ did not start</Text>
      ) : state === 'stopped' ? (
        <Text color="yellow" bold>○ stopped</Text>
      ) : state === 'idle' ? (
        <Text color="yellow" bold>○ not started</Text>
      ) : (
        <Text color="red" bold>– not configured</Text>
      )

    const glyph = { wait: '·', run: '◌', done: '✓', fail: '✗', skip: '–' } as const
    const tone = { wait: undefined, run: 'yellow', done: 'green', fail: 'red', skip: undefined } as const
    const how = confirmSandbox ? 'asks you first' : 'sends them here without asking'

    const explain =
      state === 'ready'
        ? null
        : state === 'starting'
          ? 'Jobs sent now wait for it and then run.'
          : state === 'failed'
            ? `/${COMMAND} restart tries again. Commands run on your machine meanwhile.`
            : state === 'stopped' || state === 'idle'
              ? `Run /${COMMAND} to start it. Jev ${confirmSandbox ? 'offers to start it' : 'starts it'} when it spots a sandbox job.`
              : `Set ${missing.join(', ')} in the plugin's options (settings.json, pluginConfigs["${$.plugin.name}@skills-dir"].options).`

    const showSteps = steps.length > 0 && state !== 'idle' && state !== 'off'
    const withPatch = [...jobs].reverse().find(x => x.report?.patchBytes && !x.applied)

    return (
      <Box flexDirection="column">
        <Text bold>{fit('Vercel Sandbox')}</Text>
        {badge}

        {showSteps ? (
          <Box key="steps" flexDirection="column" marginTop={1}>
            {steps.map(s => (
              <Box key={`step:${s.key}`} flexDirection="column">
                <Box flexDirection="row">
                  <Text color={tone[s.state]}>{`${glyph[s.state]} `}</Text>
                  <Text dimColor={s.state === 'wait' || s.state === 'skip'}>{fit(s.label, width - 2)}</Text>
                </Box>
                {s.detail ? <Text dimColor wrap="wrap">{`  ${s.detail}`}</Text> : null}
              </Box>
            ))}
          </Box>
        ) : null}

        {state === 'ready' ? (
          <Box key="ready" flexDirection="column" marginTop={1}>
            <Text color="green" wrap="wrap">
              {`Jev checks each command Claude runs. Tests, someone else's repo, an unknown installer, a bulk change or a clean build: it ${how}, and they run here, not on your machine.`}
            </Text>
            {info ? <Text dimColor>{fit(`${info.name} · ${info.region} · ${info.vcpus} vCPU · ${info.memory} MB`)}</Text> : null}
            {workspace ? <Text dimColor>{fit(`${plural(workspace.files, 'file')} · ${megabytes(workspace.bytes)} · ${workspace.dir}`)}</Text> : null}
            {left !== null ? <Text dimColor>{fit(`stops in ${left}m`)}</Text> : null}
          </Box>
        ) : null}
        {explain ? (
          <Box key="explain" marginTop={1}>
            <Text wrap="wrap">{explain}</Text>
          </Box>
        ) : null}

        <Box key="jev-head" marginTop={1}>
          <Text bold color="cyan">Jev</Text>
        </Box>
        <Text dimColor>{fit(`${backend} · ${confirmSandbox ? 'asks first' : 'no questions'}`)}</Text>
        <Text dimColor>{fit(`${tally.detected} detected · ${tally.sandboxed} sandboxed · ${tally.local} local`)}</Text>
        {always.size ? <Text dimColor>{fit(`always: ${[...always].join(', ')}`)}</Text> : null}

        <Box key="jobs-head" marginTop={1}>
          <Text bold color="cyan">{`Jobs (${jobs.length})`}</Text>
        </Box>
        {jobs.length === 0 ? <Text dimColor>none yet</Text> : null}
        {jobs
          .slice()
          .reverse()
          .map(j => {
            const busy = j.state === 'queued' || j.state === 'syncing' || j.state === 'running'
            const mark = busy ? '◌ ' : j.state === 'error' ? '✗ ' : j.exitCode === 0 ? '✓ ' : '! '
            const color = busy ? 'yellow' : j.state === 'error' ? 'red' : j.exitCode === 0 ? 'green' : 'yellow'
            const end = busy ? ` ${j.state}` : j.state === 'error' ? ' failed' : ` ${j.exitCode ?? '?'}`
            const lead = `${j.id} `
            const detail =
              j.state === 'error'
                ? j.error
                : [sourceText(j), j.report ? describeChanges(j.report.changes, 2) : '', j.report?.patchBytes ? (j.applied ? 'patch applied' : 'patch') : '']
                    .filter(Boolean)
                    .join(' · ')
            return (
              <Box key={`job:${j.id}`} flexDirection="column">
                <Box flexDirection="row">
                  <Text color={color}>{mark}</Text>
                  <Text bold>{lead}</Text>
                  <Text>{fit(j.short, width - 2 - lead.length - end.length)}</Text>
                  <Text dimColor>{end}</Text>
                </Box>
                {detail ? <Text dimColor>{fit(`  ${detail}`)}</Text> : null}
              </Box>
            )
          })}

        <Box key="toolbar" marginTop={1} flexDirection="row" columnGap={1}>
          {credentials && state !== 'starting' ? <Button key="restart" label={state === 'ready' ? 'restart' : 'start'} hotkey="r" onPress={noop} /> : null}
          {credentials && state === 'ready' ? <Button key="stop" label="stop" onPress={noop} /> : null}
          {withPatch ? <Button key="apply" label={`apply ${withPatch.id}`} onPress={noop} /> : null}
          <Button key="close" label="close" onPress={noop} />
        </Box>
      </Box>
    )
  })
}

files.hooks/judge.ts:
/**
 * jev-vercel-sandbox — the detector: TypeSafe's Jev asked whether one Bash
 * command is one of the jobs a sandbox is for.
 *
 * Whether a command may run on the person's machine at all is not asked here:
 * auto mode and jev-guardrails decide that. This asks only whether the command
 * is better done in a Vercel Sandbox (a long test run, someone else's repo, an
 * unknown installer, a bulk change to preview, a clean build), and each answer
 * comes with the profile the job runs under.
 *
 * No `$` and no I/O here. The wire shapes are jev-auto-mode's (TypeSafe's
 * System One API and the Vercel AI Gateway's evaluation-model endpoint, both
 * with `ai-gateway-protocol-version`); the battery is this mod's own.
 */

export type Provider = 'typesafe' | 'gateway'

export const DEFAULT_BASE_URL: Record<Provider, string> = {
  typesafe: 'https://api.typesafe.ai',
  gateway: 'https://ai-gateway.vercel.sh/v4/ai',
}

export const DEFAULT_MODEL: Record<Provider, string> = {
  typesafe: 'jev-latest',
  gateway: 'typesafe-ai/jev',
}

/** `@ai-sdk/gateway`'s AI_GATEWAY_PROTOCOL_VERSION. */
const AI_GATEWAY_PROTOCOL_VERSION = '0.0.1'

export function selectProvider(forced: string, typesafeKey: string, gatewayKey: string): Provider | null {
  if (forced === 'builtin') return null
  if (forced === 'typesafe') return typesafeKey ? 'typesafe' : null
  if (forced === 'gateway') return gatewayKey ? 'gateway' : null
  if (typesafeKey) return 'typesafe'
  if (gatewayKey) return 'gateway'
  return null
}

export function endpoint(provider: Provider, baseUrl: string): string {
  const root = baseUrl.replace(/\/+$/, '')
  return provider === 'typesafe' ? `${root}/v1/systemone` : `${root}/evaluation-model`
}

export type UseCase = 'tests' | 'external_repo' | 'untrusted_code' | 'repo_change' | 'clean_build'

/** Which copy of the project a job starts from. */
export type WorkspaceKind = 'current' | 'none'
/** What a job hands back: its output, or also the files it changed and a patch of them. */
export type Returns = 'output' | 'changes' | 'patch'

export type Profile = {
  /** How the person reads it in the question and the pane. */
  label: string
  workspace: WorkspaceKind
  background: boolean
  returns: Returns
  /** Also list the files it wrote outside the job's folder and the processes it left. */
  watch: boolean
}

export const PROFILES: Record<UseCase, Profile> = {
  tests: { label: 'a long test, lint or typecheck run', workspace: 'current', background: true, returns: 'output', watch: false },
  external_repo: { label: "someone else's repository to clone and run", workspace: 'none', background: false, returns: 'output', watch: false },
  untrusted_code: { label: 'an installer or script of unknown origin', workspace: 'none', background: false, returns: 'output', watch: true },
  repo_change: { label: 'a bulk change to the project, to preview first', workspace: 'current', background: false, returns: 'patch', watch: false },
  clean_build: { label: 'a build from a clean checkout', workspace: 'current', background: true, returns: 'output', watch: false },
}

export const USE_CASES = Object.keys(PROFILES) as UseCase[]

type Question = { instructions: string; yes: string; no: string }

/** One yes/no question per use case: is this command that kind of job? */
export const BATTERY: Record<UseCase, Question> = {
  tests: {
    instructions:
      "Is this shell command a project's full test suite, lint or typecheck run that takes a while and whose result the agent can wait for (for example npm test, pytest, go test ./..., cargo test, tsc --noEmit, eslint .)? A single quick test file does not count.",
    yes: 'It is a long check the agent could run elsewhere and keep working.',
    no: 'It is not a test, lint or typecheck run, or it is a quick one.',
  },
  external_repo: {
    instructions:
      'Does this shell command clone, download or run a repository or project that is not the one the agent is working in (for example git clone of another repo followed by its install or tests)?',
    yes: "It works on someone else's code.",
    no: 'It works only on the current project.',
  },
  untrusted_code: {
    instructions:
      'Does this shell command download and run code whose origin is not already part of the project: a script piped to a shell, a package or tool installed or run for the first time, a downloaded binary (for example curl ... | sh, npx some-new-package, pip install from a URL)?',
    yes: 'It runs code that has not been reviewed.',
    no: 'It runs only code already in the project or on the machine.',
  },
  repo_change: {
    instructions:
      'Does this shell command change many of the project\'s files at once in a way worth previewing before it touches them: deleting folders, a codemod, a mass rename or search-and-replace, regenerating files, a dependency upgrade that rewrites lockfiles (for example rm -rf src/legacy, npx jscodeshift, sed -i across many files, npm update)?',
    yes: 'It rewrites or removes many project files at once.',
    no: 'It reads, or changes one or two files.',
  },
  clean_build: {
    instructions:
      'Is this shell command a full build or install of the project from scratch, where a clean machine would tell whether it builds without local caches (for example npm ci && npm run build, rm -rf node_modules && npm install, a docker-free release build)?',
    yes: 'It is a from-scratch build or install.',
    no: 'It is not a full build or install.',
  },
}

const SAFE_PROGRAMS = new Set([
  'ls', 'pwd', 'cat', 'head', 'tail', 'wc', 'echo', 'printf', 'which', 'type', 'file', 'stat', 'du', 'df',
  'grep', 'egrep', 'rg', 'tree', 'date', 'whoami', 'uname', 'basename', 'dirname', 'realpath', 'sort', 'uniq', 'diff', 'true',
])
const SAFE_GIT = new Set(['status', 'log', 'diff', 'show', 'rev-parse', 'blame', 'ls-files', 'describe'])
// `git branch -D x` and `git remote remove origin` write: these two are reads only with listing flags
const LISTING_GIT = new Set(['branch', 'remote'])
const LISTING_FLAGS = new Set(['-a', '-r', '-v', '-vv', '--all', '--remotes', '--list', '--verbose', '--show-current'])

/**
 * A command that plainly only reads: one program from a short list, no shell
 * operators, redirects or substitutions. None of the use cases can be one of
 * these, so they stay local without a call to the detector.
 */
export function isPlainRead(command: string): boolean {
  const c = command.trim()
  if (!c || /[;&|<>`$(){}\n\\]/.test(c)) return false
  const words = c.split(/\s+/)
  const program = words[0]!
  if (program === 'git') {
    const sub = words[1] ?? ''
    if (LISTING_GIT.has(sub)) return words.slice(2).every(w => LISTING_FLAGS.has(w))
    return SAFE_GIT.has(sub) && !words.some(w => /^--(output|exec)/.test(w))
  }
  if (program === 'find') return !words.some(w => /^-(delete|exec|execdir|ok|okdir|fprint|fls)/.test(w))
  return SAFE_PROGRAMS.has(program)
}

/** What the detector reads: the user's request, then the command, whole. */
export function stateText(intent: string, command: string, cwd: string): string {
  return [
    "The user's latest request to an AI coding agent:",
    intent.trim() ? intent.trim().slice(0, 2000) : '(none recorded)',
    '',
    `The agent is about to run this shell command${cwd ? ` in ${cwd}` : ''}:`,
    command,
  ].join('\n')
}

function yesNo(provider: Provider, q: Question): Record<string, unknown> {
  if (provider === 'typesafe') return { type: 'noul', instructions: q.instructions, criteria: { true: q.yes, false: q.no } }
  return { type: 'boolean', instructions: `${q.instructions} Yes: ${q.yes} No: ${q.no}` }
}

/** The battery for the use cases turned on, one question each. */
export function requestBody(provider: Provider, state: string, model: string, cases: readonly UseCase[] = USE_CASES): string {
  const questions: Record<string, unknown> = {}
  for (const c of cases) questions[c] = yesNo(provider, BATTERY[c])
  return JSON.stringify(provider === 'typesafe' ? { model, state, questions } : { state, questions })
}

export function requestHeaders(provider: Provider, apiKey: string, model: string): Record<string, string> {
  const common = { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` }
  if (provider === 'typesafe') return common
  return {
    ...common,
    'ai-gateway-auth-method': 'api-key',
    'ai-model-id': model,
    'ai-gateway-protocol-version': AI_GATEWAY_PROTOCOL_VERSION,
    'ai-evaluation-model-specification-version': '4',
  }
}

export type Judgement = Partial<Record<UseCase, number>>

/** Reads either backend's answer; one with any asked use case unanswered reads as none. */
export function readJudgement(text: string, cases: readonly UseCase[] = USE_CASES): Judgement | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (parsed === null || typeof parsed !== 'object') return null
  const answers = (parsed as { answers?: Record<string, Record<string, unknown>> }).answers
  if (!answers || typeof answers !== 'object') return null
  const out: Judgement = {}
  for (const c of cases) {
    const a = answers[c]
    const p = typeof a?.noul === 'number' ? a.noul : typeof a?.probability === 'number' ? a.probability : null
    if (p === null) return null
    out[c] = p
  }
  return out
}

export type Detection = {
  /** The use case found, or null when the command is none of them. */
  useCase: UseCase | null
  probability: number | null
  by: 'read-only' | 'jev' | 'built-in' | 'no answer'
}

/** The likeliest use case when it reaches `threshold`, else none. */
export function decide(j: Judgement, threshold: number): Detection {
  let top: UseCase | null = null
  for (const c of Object.keys(j) as UseCase[]) if (top === null || j[c]! > j[top]!) top = c
  const p = top === null ? null : j[top]!
  if (top !== null && p !== null && p >= threshold) return { useCase: top, probability: p, by: 'jev' }
  return { useCase: null, probability: p, by: 'jev' }
}

/** The labels the engine's small classifier picks from when no Jev key is set. */
export function builtinLabels(cases: readonly UseCase[] = USE_CASES): string[] {
  return ['none', ...cases]
}

/** The rubric the engine's small classifier reads when no Jev key is set. */
export function classifyText(state: string, cases: readonly UseCase[] = USE_CASES): string {
  return [
    'You decide whether a shell command an AI coding agent is about to run is one of the jobs a remote sandbox is for. Answer with the job\'s label, or "none".',
    ...cases.map(c => `- ${c}: ${BATTERY[c].instructions}`),
    'Ordinary development work (reading, editing a file, a quick single test, git commits, starting the dev server) is "none".',
    '',
    state,
  ].join('\n')
}

/** The use cases a comma-separated option turns on; empty or unknown names turn on none of their own. */
export function parseUseCases(value: string): UseCase[] {
  if (!value.trim()) return [...USE_CASES]
  const wanted = new Set(value.split(',').map(s => s.trim().toLowerCase().replace(/-/g, '_')))
  return USE_CASES.filter(c => wanted.has(c))
}

export function describeJudgement(j: Judgement | null, ms: number): string {
  const took = ` · ${Math.round(ms)}ms`
  if (!j) return `no answer${took}`
  return (
    (Object.entries(j) as [UseCase, number][])
      .sort((a, b) => b[1] - a[1])
      .map(([c, p]) => `${c} ${p.toFixed(2)}`)
      .join(' · ') + took
  )
}

export function detectionReason(d: Detection): string {
  if (d.by === 'read-only') return 'plain read'
  if (d.by === 'no answer') return 'the detector gave no answer'
  if (!d.useCase) return d.by === 'built-in' ? 'built-in classifier: none' : `none${d.probability === null ? '' : ` (top ${d.probability.toFixed(2)})`}`
  const p = d.probability === null ? '' : ` ${d.probability.toFixed(2)}`
  return `${d.useCase.replace(/_/g, ' ')}${p}${d.by === 'built-in' ? ' (built-in classifier)' : ''}`
}

/** One line for the transcript, the pane and the status: the command, cut to fit. */
export function shortCommand(command: string, max = 60): string {
  const one = command.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

files.hooks/vercel.ts:
/**
 * jev-vercel-sandbox — the Vercel Sandbox REST client.
 *
 * A mod runs without node_modules, so `@vercel/sandbox` is not available: this
 * speaks its HTTP API directly, through a `fetch` the hooks module hands in
 * (`(url, init) => $.http.fetch(url, init)`), so nothing here touches `$`.
 *
 * The endpoints are Vercel's REST API reference (vercel.com/docs/rest-api/sandboxes),
 * called the way `@vercel/sandbox` 3.5.0 calls them (dist/api-client/api-client.js):
 *
 *   POST /v3/sandboxes?teamId=…                       create → { sandbox, session, routes }
 *   GET  /v2/sandboxes/sessions/{id}?teamId=…         → { session, routes }
 *   POST /v2/sandboxes/sessions/{id}/cmd?teamId=…     { command, args, cwd, env, sudo, wait: true, logs: true, timeout }
 *                                                     → application/x-ndjson: { command } · { stream, data }… · { command: { exitCode } }
 *   POST /v2/sandboxes/sessions/{id}/stop?teamId=…    → { session }
 *
 * Base URL https://api.vercel.com (the SDK uses the equivalent
 * https://vercel.com/api), `Authorization: Bearer <token>`. An error body is
 * `{ error: { message } }`. `persistent` defaults to true on the server, so it
 * is always sent.
 */
import type { HttpInit, HttpResponse } from 'claude-code'

export type Fetch = (url: string, init: HttpInit) => Promise<HttpResponse>

export const DEFAULT_API_URL = 'https://api.vercel.com'

export type Credentials = { token: string; teamId: string; projectId: string }

export type SessionStatus = 'pending' | 'running' | 'stopping' | 'stopped' | 'failed' | 'aborted' | 'snapshotting'

export type SandboxInfo = {
  /** The sandbox's name (the SDK's `sandbox.name`). */
  name: string
  /** The current session: commands and stop go to it. */
  sessionId: string
  status: SessionStatus
  region: string
  vcpus: number
  memory: number
  /** The session's timeout, in ms. */
  timeout: number
  cwd: string
  image?: string
  /** Epoch ms the session started (or was requested, while pending). */
  startedAt: number
}

export type CreateOptions = {
  timeoutMs: number
  image?: string
  vcpus?: number
  persistent: boolean
}

export type RunResult = {
  exitCode: number | null
  stdout: string
  stderr: string
  durationMs?: number
  /** A `{ stream: "error" }` line, or a stream that ended before the command did. */
  error?: string
}

/** base64url → text, without `atob` (the mod runtime's lib is es2023 only). */
function decodeBase64Url(s: string): string {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
  let bits = 0
  let value = 0
  const bytes: number[] = []
  for (const ch of s.replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_')) {
    const i = alphabet.indexOf(ch)
    if (i < 0) throw new Error('not base64url')
    value = (value << 6) | i
    bits += 6
    if (bits >= 8) {
      bits -= 8
      bytes.push((value >> bits) & 0xff)
    }
  }
  // UTF-8 without TextDecoder (not in the es2023 lib either)
  return decodeURIComponent(bytes.map(b => `%${b.toString(16).padStart(2, '0')}`).join(''))
}

/**
 * The claims a Vercel OIDC token carries (`owner_id` is the team,
 * `project_id` the project), as the SDK's `decodeUnverifiedToken` reads them.
 * Null for an access token, which is not a JWT.
 */
export function oidcClaims(token: string): { teamId: string; projectId?: string } | null {
  const parts = token.split('.')
  if (parts.length !== 3) return null
  try {
    const payload = JSON.parse(decodeBase64Url(parts[1]!)) as { owner_id?: unknown; project_id?: unknown }
    if (typeof payload.owner_id !== 'string') return null
    return { teamId: payload.owner_id, projectId: typeof payload.project_id === 'string' ? payload.project_id : undefined }
  } catch {
    return null
  }
}

/**
 * Credentials from the options (or the env fallbacks): an access token needs
 * the team and project ids beside it; an OIDC token carries both itself.
 */
export function resolveCredentials(
  token: string,
  teamId: string,
  projectId: string,
): { ok: true; credentials: Credentials; kind: 'access token' | 'oidc token' } | { ok: false; missing: string[] } {
  const t = token.trim()
  const claims = t ? oidcClaims(t) : null
  const team = teamId.trim() || claims?.teamId || ''
  const project = projectId.trim() || claims?.projectId || ''
  const missing = [!t && 'vercelToken', !team && 'vercelTeamId', !project && 'vercelProjectId'].filter((m): m is string => !!m)
  if (missing.length) return { ok: false, missing }
  return { ok: true, credentials: { token: t, teamId: team, projectId: project }, kind: claims ? 'oidc token' : 'access token' }
}

export function apiUrl(base: string, path: string, teamId: string): string {
  return `${base.replace(/\/+$/, '')}${path}?teamId=${encodeURIComponent(teamId)}`
}

export function headers(c: Credentials): Record<string, string> {
  return { authorization: `Bearer ${c.token}`, 'content-type': 'application/json', 'user-agent': 'jev-vercel-sandbox (claude-code mod)' }
}

export function createBody(c: Credentials, o: CreateOptions): string {
  const body: Record<string, unknown> = {
    projectId: c.projectId,
    ports: [],
    timeout: o.timeoutMs,
    persistent: o.persistent,
  }
  if (o.image) body.image = o.image
  if (o.vcpus) body.resources = { vcpus: o.vcpus }
  return JSON.stringify(body)
}

/** The Bash tool's command, run by bash in the sandbox with no local env forwarded. */
export function commandBody(command: string, timeoutMs: number, cwd?: string): string {
  return execBody('bash', ['-c', command], timeoutMs, cwd)
}

/** Any program by its argv (the mod's own upload and bookkeeping scripts). */
export function execBody(command: string, args: readonly string[], timeoutMs: number, cwd?: string): string {
  return JSON.stringify({
    command,
    args,
    cwd: cwd || undefined,
    env: {},
    sudo: false,
    wait: true,
    logs: true,
    timeout: timeoutMs,
  })
}

/** The server's `{ error: { message } }`, else the status and the start of the body. */
export function errorOf(r: HttpResponse): string {
  try {
    const m = (JSON.parse(r.text) as { error?: { message?: unknown } }).error?.message
    if (typeof m === 'string' && m) return `${r.status}: ${m}`
  } catch {}
  return `${r.status}${r.text ? `: ${r.text.slice(0, 200)}` : ''}`
}

function num(v: unknown, fallback = 0): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : fallback
}

function readSessionObject(session: Record<string, unknown>, sandbox?: Record<string, unknown>): SandboxInfo | null {
  if (typeof session.id !== 'string' || typeof session.status !== 'string') return null
  return {
    name: typeof sandbox?.name === 'string' ? sandbox.name : session.id,
    sessionId: session.id,
    status: session.status as SessionStatus,
    region: typeof session.region === 'string' ? session.region : '',
    vcpus: num(session.vcpus),
    memory: num(session.memory),
    timeout: num(session.timeout),
    cwd: typeof session.cwd === 'string' ? session.cwd : '',
    image: typeof sandbox?.image === 'string' ? sandbox.image : undefined,
    startedAt: num(session.startedAt, num(session.requestedAt, num(session.createdAt))),
  }
}

/** `{ sandbox, session, routes }` (create) or `{ session, routes }` (get). */
export function readSandbox(text: string, previousName?: string): SandboxInfo | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object') return null
  const { session, sandbox } = parsed as { session?: unknown; sandbox?: unknown }
  if (!session || typeof session !== 'object') return null
  const info = readSessionObject(session as Record<string, unknown>, sandbox && typeof sandbox === 'object' ? (sandbox as Record<string, unknown>) : undefined)
  if (info && !sandbox && previousName) info.name = previousName
  return info
}

/**
 * The command endpoint's ndjson, read whole: the first line names the
 * command, log lines follow, and a line with `command.exitCode` ends it.
 */
export function readCommandStream(text: string): RunResult {
  const out: RunResult = { exitCode: null, stdout: '', stderr: '' }
  let finished = false
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    let chunk: Record<string, unknown>
    try {
      chunk = JSON.parse(line) as Record<string, unknown>
    } catch {
      continue
    }
    const command = chunk.command as { exitCode?: unknown; durationMs?: unknown } | undefined
    if (command && typeof command === 'object') {
      if (typeof command.exitCode === 'number') {
        out.exitCode = command.exitCode
        if (typeof command.durationMs === 'number') out.durationMs = command.durationMs
        finished = true
      }
      continue
    }
    if (chunk.stream === 'stdout' && typeof chunk.data === 'string') out.stdout += chunk.data
    else if (chunk.stream === 'stderr' && typeof chunk.data === 'string') out.stderr += chunk.data
    else if (chunk.stream === 'error') {
      const d = chunk.data as { code?: unknown; message?: unknown } | undefined
      out.error = `${typeof d?.code === 'string' ? d.code : 'error'}: ${typeof d?.message === 'string' ? d.message : 'the sandbox reported an error'}`
    }
  }
  if (!finished && !out.error) out.error = 'the stream ended before the command finished'
  return out
}

export type Client = {
  create(o: CreateOptions): Promise<SandboxInfo>
  get(s: SandboxInfo): Promise<SandboxInfo>
  /** The Bash tool's command, by bash, in `cwd` (the sandbox's own when absent). */
  run(s: SandboxInfo, command: string, timeoutMs: number, cwd?: string): Promise<RunResult>
  /** A bash script of the mod's own with positional arguments (`bash -c script _ …args`). */
  script(s: SandboxInfo, script: string, args: readonly string[], timeoutMs: number): Promise<RunResult>
  stop(s: SandboxInfo): Promise<void>
}

/** The calls this mod makes, over the fetch it is handed. Each throws with the API's message on a non-2xx. */
export function client(fetch: Fetch, c: Credentials, base = DEFAULT_API_URL): Client {
  const call = async (path: string, init: HttpInit) => {
    const r = await fetch(apiUrl(base, path, c.teamId), { ...init, headers: headers(c) })
    if (!r.ok) throw new Error(`Vercel Sandbox ${errorOf(r)}`)
    return r
  }
  return {
    async create(o) {
      const r = await call('/v3/sandboxes', { method: 'POST', body: createBody(c, o) })
      const info = readSandbox(r.text)
      if (!info) throw new Error('Vercel Sandbox: unreadable create response')
      return info
    },
    async get(s) {
      const r = await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}`, { method: 'GET' })
      const info = readSandbox(r.text, s.name)
      if (!info) throw new Error('Vercel Sandbox: unreadable session response')
      return { ...info, image: info.image ?? s.image }
    },
    async run(s, command, timeoutMs, cwd) {
      const r = await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}/cmd`, {
        method: 'POST',
        body: commandBody(command, timeoutMs, cwd || s.cwd),
      })
      return readCommandStream(r.text)
    },
    async script(s, script, args, timeoutMs) {
      const r = await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}/cmd`, {
        method: 'POST',
        body: execBody('bash', ['-c', script, 'jev', ...args], timeoutMs, s.cwd),
      })
      return readCommandStream(r.text)
    },
    async stop(s) {
      await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}/stop`, { method: 'POST' })
    },
  }
}

files.hooks/workspace.ts:
/**
 * jev-vercel-sandbox — copying the project into the sandbox.
 *
 * `$.http.fetch` sends text only, so the SDK's `fs/write` (a gzip tar body) is
 * out of reach. Instead the hooks module packs the project with the local
 * `tar`, reads the archive back as base64, and this file's scripts rebuild it
 * inside the sandbox through the command endpoint: the base64 is appended to a
 * file a few arguments at a time, then decoded and unpacked, and a git
 * baseline is committed. Before each job the project's current state is
 * synced as a patch (`git diff --binary` between two trees the hooks module
 * builds with a throwaway index), and the job runs in its own worktree, so a
 * job always starts from the files as they are and two jobs never share a folder.
 *
 * Pure helpers only: nothing here touches `$`.
 */

/** Where the base64 is assembled inside the sandbox. */
export const UPLOAD_FILE = '/tmp/jev-workspace.b64'

/** One argument's size: well under Linux's 128 KiB per-argument limit. */
export const ARG_BYTES = 100_000
/** Arguments per command call, so one request body stays near 400 KB. */
export const ARGS_PER_CALL = 4
/**
 * `$.fs.read` rejects files over 4 MiB, so a bigger archive is `split` into
 * parts of this size. A multiple of 3, so every part but the last encodes to
 * base64 without padding and the parts' base64 concatenates into one stream.
 */
export const PART_BYTES = 3_000_000

/** Files that hold credentials: never copied, whatever git says about them. */
const SECRET_NAMES = [
  /^\.env$/,
  /^\.env\.(?!example$|sample$|template$|dist$)[^/]+$/,
  /^\.dev\.vars$/,
  /^\.npmrc$/,
  /^\.pypirc$/,
  /^\.netrc$/,
  /^\.git-credentials$/,
  /^\.pgpass$/,
  /\.tfstate(\.backup)?$/,
  /\.(pem|key|p12|pfx|jks|keystore|ppk)$/i,
  /^id_(rsa|dsa|ecdsa|ed25519)(\.pub)?$/,
  /^credentials(\.json)?$/,
]
const SECRET_DIRS = ['.git', '.ssh', '.aws', '.gnupg', '.kube', '.docker', '.terraform', 'node_modules', '.vercel', '.claude']

/** True for a path the upload leaves out: a credential file, or one inside a folder that never goes. */
export function isExcluded(path: string): boolean {
  const parts = path.split('/')
  const name = parts[parts.length - 1] ?? ''
  if (parts.slice(0, -1).some(dir => SECRET_DIRS.includes(dir))) return true
  return SECRET_NAMES.some(re => re.test(name))
}

/** `-z` / `-print0` output → paths, `./` dropped. */
export function nulList(text: string): string[] {
  return text
    .split('\0')
    .map(p => p.replace(/^\.\//, ''))
    .filter(Boolean)
}

/** What goes up: listed files, minus the deleted ones git still lists, minus the excluded. */
export function filesToUpload(listed: string[], deleted: string[] = []): { files: string[]; excluded: string[] } {
  const gone = new Set(deleted)
  const files: string[] = []
  const excluded: string[] = []
  for (const p of new Set(listed)) {
    if (gone.has(p)) continue
    if (isExcluded(p)) excluded.push(p)
    else files.push(p)
  }
  return { files: files.sort(), excluded: excluded.sort() }
}

/** The base64 cut into argument lists, one list per command call. */
export function uploadBatches(base64: string, argBytes = ARG_BYTES, perCall = ARGS_PER_CALL): string[][] {
  const args: string[] = []
  for (let i = 0; i < base64.length; i += argBytes) args.push(base64.slice(i, i + argBytes))
  const batches: string[][] = []
  for (let i = 0; i < args.length; i += perCall) batches.push(args.slice(i, i + perCall))
  return batches
}

/** bash -c script, `$1` the file: empties it. */
export const TRUNCATE_SCRIPT = ': > "$1"'
/** bash -c script, `$1` the file, the rest base64 pieces: appends them in order. */
export const APPEND_SCRIPT = 'f="$1"; shift; printf %s "$@" >> "$f"'
/** Git inside the sandbox: the baseline, every sync and every job's worktree need it. */
const ENSURE_GIT = [
  'if ! command -v git >/dev/null 2>&1; then',
  '  (sudo -n dnf install -y -q git || sudo -n apt-get install -y -q git) >/dev/null 2>&1 || true',
  'fi',
]
const IDENTITY = '-c user.name=jev-vercel-sandbox -c user.email=jev@sandbox.invalid'
/**
 * bash -c script, `$1` the base64 file, `$2` the folder: unpacks the project
 * there and commits a baseline when git exists. Prints `git` or `no-git` last.
 */
export const EXTRACT_SCRIPT = [
  'set -e',
  'mkdir -p "$2"',
  'base64 -d "$1" | tar -xzf - -C "$2"',
  'rm -f "$1"',
  'cd "$2"',
  ...ENSURE_GIT,
  'if command -v git >/dev/null 2>&1; then',
  '  git init -q',
  '  git add -A',
  `  git ${IDENTITY} commit -q --allow-empty -m baseline`,
  '  echo git',
  'else',
  '  echo no-git',
  'fi',
].join('\n')

/** Where a sync's patch is assembled inside the sandbox. */
export const SYNC_FILE = '/tmp/jev-sync.b64'
/**
 * bash -c script, `$1` the base64 patch, `$2` the project folder, `$3` the
 * commit message: brings the sandbox's copy to the project's current state.
 */
export const SYNC_SCRIPT = [
  'set -e',
  'base64 -d "$1" > /tmp/jev-sync.patch',
  'rm -f "$1"',
  'cd "$2"',
  'git apply --binary --whitespace=nowarn /tmp/jev-sync.patch',
  'rm -f /tmp/jev-sync.patch',
  'git add -A',
  `git ${IDENTITY} commit -q --allow-empty -m "$3"`,
].join('\n')

/** The processes running now, without this script's own. */
const PROCESSES = `ps -eo pid=,ppid=,comm= 2>/dev/null | awk -v me=$$ '$1!=me && $2!=me && $1!=2 && $2!=2 {print $1" "$3}' | sort`
/**
 * bash -c script, `$1` how the job starts (`current`, `none`, `git`), `$2` the
 * project folder, `$3` the job's folder, `$4` a git URL, `$5` its ref, `$6`
 * the working directory inside the job's folder: makes
 * the job's folder (a worktree of the synced project, a clone, or an empty
 * repository), then marks the time and the processes so the report can tell
 * what the job did.
 */
export const PREPARE_SCRIPT = [
  'set -e',
  'rm -rf "$3"',
  'mkdir -p "$(dirname "$3")"',
  ...ENSURE_GIT,
  'case "$1" in',
  '  current) git -C "$2" worktree add -q --detach "$3" HEAD ;;',
  '  git) if [ -n "$5" ]; then git clone -q -- "$4" "$3" && git -C "$3" checkout -q "$5" --; else git clone -q --depth 1 -- "$4" "$3"; fi ;;',
  `  *) mkdir -p "$3" && git -C "$3" init -q && git -C "$3" ${IDENTITY} commit -q --allow-empty -m empty ;;`,
  'esac',
  'if [ -n "$6" ]; then mkdir -p "$3/$6"; fi',
  'touch "$3.marker"',
  `${PROCESSES} > "$3.ps" || true`,
].join('\n')
/**
 * bash -c script, `$1` the job's folder, `$2` 1 to list what the job did
 * outside it, `$3` 1 to keep a patch of its changes: prints `@@changes` and
 * git's porcelain status, `@@patch <bytes>`, then `@@outside` (files written
 * since the job began, outside the jobs, /tmp and the kernel's folders) and
 * `@@processes` (processes started since then and still running).
 */
export const REPORT_SCRIPT = [
  'cd "$1" || exit 0',
  'if git rev-parse --git-dir >/dev/null 2>&1; then',
  '  git add -A >/dev/null 2>&1',
  '  echo "@@changes"',
  '  git status --porcelain=v1 --no-renames',
  '  if [ "$3" = 1 ]; then',
  '    git diff --cached --binary --full-index HEAD > "$1.patch"',
  `    echo "@@patch $(wc -c < "$1.patch" | tr -d ' ')"`,
  '  fi',
  'fi',
  'if [ "$2" = 1 ]; then',
  '  echo "@@outside"',
  '  find / -xdev \\( -path /proc -o -path /sys -o -path /dev -o -path /tmp -o -path /run -o -path /var/tmp -o -path /var/cache -o -path /var/log -o -path "$(dirname "$1")" \\) -prune -o -newer "$1.marker" \\( -type f -o -type l \\) -print 2>/dev/null | head -n 200',
  '  echo "@@processes"',
  `  ${PROCESSES} > "$1.ps2" || true`,
  '  comm -13 "$1.ps" "$1.ps2" 2>/dev/null | head -n 50',
  'fi',
].join('\n')
/** bash -c script, `$1` a job's patch: prints it, refusing one that is not UTF-8 text (it would not survive the trip). */
export const PATCH_SCRIPT = [
  'test -f "$1" || { echo "the job kept no patch" >&2; exit 3; }',
  'if command -v iconv >/dev/null 2>&1 && ! iconv -f UTF-8 -t UTF-8 "$1" >/dev/null 2>&1; then echo "the patch holds text that is not UTF-8; apply it by hand" >&2; exit 3; fi',
  'cat "$1"',
].join('\n')

export type Report = { changes: Change[]; patchBytes: number | null; outside: string[]; processes: string[] }

/** REPORT_SCRIPT's output → its parts. */
export function readReport(text: string): Report {
  const out: Report = { changes: [], patchBytes: null, outside: [], processes: [] }
  let section = ''
  const status: string[] = []
  for (const line of text.split('\n')) {
    const m = /^@@(changes|patch|outside|processes)(?: (\d+))?$/.exec(line.trim())
    if (m) {
      section = m[1]!
      if (section === 'patch') out.patchBytes = Number(m[2] ?? 0)
      continue
    }
    if (!line.trim()) continue
    if (section === 'changes') status.push(line)
    else if (section === 'outside') out.outside.push(line.trim())
    else if (section === 'processes') out.processes.push(line.trim().replace(/^\d+\s+/, ''))
  }
  out.changes = readChanges(status.join('\n'))
  return out
}

/**
 * The paths a patch writes, read from the patch itself (the sandbox's own
 * file list could lie), and whether it makes a symlink, which a later write
 * could follow out of the project.
 */
export function patchTargets(patch: string): { paths: string[]; symlink: boolean } {
  const paths = new Set<string>()
  let symlink = false
  for (const line of patch.split('\n')) {
    const header = /^diff --git a\/(.+) b\/(.+)$/.exec(line)
    if (header) {
      paths.add(header[1]!)
      paths.add(header[2]!)
      continue
    }
    const moved = /^(?:rename|copy) (?:from|to) (.+)$/.exec(line)
    if (moved) paths.add(moved[1]!)
    const file = /^(?:\+\+\+|---) (?:[ab]\/)?(.+)$/.exec(line)
    if (file && file[1] !== '/dev/null') paths.add(file[1]!)
    if (/^(?:new file mode|new mode|old mode|deleted file mode) 120000$/.test(line) || /^index [0-9a-f]+\.\.[0-9a-f]+ 120000$/.test(line)) symlink = true
  }
  return { paths: [...paths].map(p => p.replace(/^"(.*)"$/, '$1')), symlink }
}

/** A URL the sandbox may clone: https only (no file://, ext:: or option-looking strings). */
export function isGitUrl(url: string): boolean {
  return /^https:\/\/[^\s'"`]+$/.test(url)
}

/** A branch, tag or commit to check out: no spaces, never an option. */
export function isGitRef(ref: string): boolean {
  return /^[A-Za-z0-9._/-]+$/.test(ref) && !ref.startsWith('-') && !ref.includes('..')
}

export type Change = { path: string; kind: 'added' | 'modified' | 'deleted' }

/** `git status --porcelain=v1` after `add -A` → the changed files. */
export function readChanges(text: string): Change[] {
  const out: Change[] = []
  for (const line of text.split('\n')) {
    if (line.length < 4) continue
    const code = line.slice(0, 2)
    let path = line.slice(3)
    if (path.startsWith('"') && path.endsWith('"')) path = path.slice(1, -1)
    const kind = code.includes('D') ? 'deleted' : code.includes('A') || code.includes('?') ? 'added' : 'modified'
    out.push({ path, kind })
  }
  return out
}

/** "3 files: +a.txt, ~b.ts, -c.md" (at most `max` named). */
export function describeChanges(changes: Change[], max = 8): string {
  if (!changes.length) return 'no files changed'
  const mark = { added: '+', modified: '~', deleted: '-' } as const
  const named = changes.slice(0, max).map(c => `${mark[c.kind]}${c.path}`)
  const more = changes.length > max ? `, … ${changes.length - max} more` : ''
  return `${changes.length} file${changes.length === 1 ? '' : 's'} changed: ${named.join(', ')}${more}`
}

/** The folder name the project gets inside the sandbox. */
export function folderName(root: string): string {
  const base = root.replace(/[\\/]+$/, '').split(/[\\/]/).pop() || 'workspace'
  return base.replace(/[^A-Za-z0-9._-]/g, '_') || 'workspace'
}

/** The session's working directory relative to the project root ('' at the root, null outside it). */
export function relativeCwd(root: string, cwd: string): string | null {
  const r = root.replace(/[\\/]+$/, '')
  const c = cwd.replace(/[\\/]+$/, '')
  if (c === r) return ''
  if (c.startsWith(`${r}/`) || c.startsWith(`${r}\\`)) return c.slice(r.length + 1).replace(/\\/g, '/')
  return null
}

export function megabytes(bytes: number): string {
  return `${(bytes / 1_048_576).toFixed(bytes < 10_485_760 ? 1 : 0)} MB`
}

files.tests/jev-vercel-sandbox.test.tsx:
// Run with: claude plugin test security/jev-vercel-sandbox
import { describe, expect, test } from 'claude-code/testing'
import type { Engine } from 'claude-code/testing'
import type { On } from 'claude-code'

type Call = { method: string; url: string; body?: { command?: string; args?: string[]; cwd?: string } & Record<string, unknown>; auth?: string }
type World = {
  env: Record<string, string>
  /** What the built-in classifier answers (no Jev key in tests). */
  label: string
  /** What the person picks in the question dialog; null dismisses it. */
  answer: string | null
  asked: string[]
  calls: Call[]
  ranLocally: string[]
  logs: string[]
  submits: string[]
  processes: { argv: readonly string[]; stdin?: string; env?: Record<string, string> }[]
  opened: number
  /** What the Vercel API answers a job's command with. */
  cmd: string
  cmdStatus: number
  createStatus: number
  /** Holds the create request this long, so a failed pack can finish first. */
  createDelayMs: number
  sessionStatus: string
  getStatus: string
  /** The compressed project's size, for the cap. */
  archiveBytes: number
  /** The tree `git write-tree` prints: change it to edit the project. */
  tree: string
  /** What `git status --porcelain` prints after a job. */
  porcelain: string
  patch: string
  /** Makes $.clock.now throw, to fail a hook mid-way. */
  nowThrows: boolean
  /** Set nowThrows once the person has answered. */
  throwAfterAnswer: boolean
  registered: string[]
  classified: number
}

const SESSION = { id: 'sbx_session_1', status: 'running', region: 'iad1', vcpus: 2, memory: 4096, timeout: 2_700_000, cwd: '/vercel/sandbox', requestedAt: 1_000, startedAt: 1_000, createdAt: 1_000 }
const SANDBOX = { name: 'sbx-quiet-owl', persistent: false, createdAt: 1_000, updatedAt: 1_000, currentSessionId: SESSION.id, status: 'running' }
const TREE0 = 'a'.repeat(40)
const TREE1 = 'b'.repeat(40)

const ndjson = (...lines: unknown[]) => lines.map(l => JSON.stringify(l)).join('\n') + '\n'
const COMMAND = { id: 'cmd_1', name: 'bash', args: ['-c', 'x'], cwd: '/vercel/sandbox', sessionId: SESSION.id, exitCode: null, startedAt: 1_000 }
const finished = (stdout = '', exitCode = 0) => ndjson({ command: COMMAND }, ...(stdout ? [{ stream: 'stdout', data: stdout }] : []), { command: { ...COMMAND, exitCode } })

/** A call to the cmd endpoint that is the mod's own script (upload, sync, prepare, report), not a job's command. */
const isScript = (c: Call) => c.url.includes('/cmd') && c.body?.args?.[2] === 'jev'
const scriptsWith = (w: World, needle: string) => w.calls.filter(c => isScript(c) && c.body!.args![1]!.includes(needle)).map(c => c.body!.args!.slice(3))
const jobCommands = (w: World) => w.calls.filter(c => c.url.includes('/cmd') && !isScript(c))

function fakeEngine(on: On, w: World) {
  on('env.get', ($, e) => ({ value: w.env[e.name] }))
  on('session.root', () => ({ value: '/repo' }))
  on('session.cwd', () => ({ value: '/repo/src' }))
  on('clock.now', () => {
    if (w.nowThrows) throw new Error('clock gone')
    return { value: 1_000 }
  })
  on('clock.sleep', () => ({ value: undefined }))
  on('model.classify', () => {
    w.classified += 1
    return { value: w.label }
  })
  on('command.register', () => ({ value: undefined }) as never)
  on('tool.register', ($, e) => {
    w.registered.push((e as { name: string }).name)
    return { value: { tool: `mcp__jev-vercel-sandbox__${(e as { name: string }).name}` } } as never
  })
  on('prompt.submit', async ($, e) => {
    w.submits.push(e.text)
    return { text: e.text } as never
  })
  on('ui.open', () => {
    w.opened += 1
    return { value: { id: 'jev-vercel-sandbox' } } as never
  })
  on('ui.invalidate', () => ({ value: undefined }) as never)
  on('ui.log', ($, e) => {
    w.logs.push(String((e as { text: unknown }).text))
    return { value: undefined }
  })
  on('ui.status', () => ({ value: undefined }))
  on('ui.toast', () => ({ value: undefined }))
  on('turn.start', async ($, e) => ({ turnId: e.turnId }))
  on('session.start', async ($, e) => ({ cwd: e.cwd }) as never)
  on('session.end', async () => ({ sessionId: 's1' }) as never)
  on('tool.call', async ($, e) => {
    if (e.tool === 'AskUserQuestion') {
      const q = (e as unknown as { questions: { question: string }[] }).questions[0]!.question
      w.asked.push(q)
      if (w.answer === null) return { deny: 'dismissed' }
      if (w.throwAfterAnswer) w.nowThrows = true
      return { result: { questions: [], answers: { [q]: w.answer } } } as never
    }
    w.ranLocally.push(String((e as { command?: unknown }).command))
    return { result: { stdout: 'local', stderr: '', interrupted: false }, text: 'local' } as never
  })
  on('process.run', ($, e) => {
    w.processes.push({ argv: e.argv, stdin: e.init?.stdin, env: e.init?.env })
    const out = (stdout: string, exitCode = 0) => ({ value: { exitCode, stdout, stderr: '' } })
    const [bin, ...args] = e.argv
    if (bin === 'git' && args[0] === 'rev-parse') return out('/repo\n')
    if (bin === 'git' && args.includes('--deleted')) return out('gone.txt\0')
    if (bin === 'git' && args[0] === 'ls-files') {
      const tracked = 'README.md\0src/app.ts\0.env\0gone.txt\0keys/deploy.pem\0'
      // untracked, and no name the credential list knows
      return out(args.includes('--others') ? `${tracked}service-account.json\0secrets.yaml\0.envrc\0` : tracked)
    }
    if (bin === 'git' && args[0] === 'write-tree') return out(`${w.tree}\n`)
    if (bin === 'mktemp') return out('/tmp/jev.X\n')
    return out('')
  })
  on('fs.stat', () => ({ value: { kind: 'file', size: w.archiveBytes, mtimeMs: 1_000, isLink: false } }))
  on('fs.read', () => ({ value: { base64: 'UFJPSkVDVA==' } }))
  on('http.fetch', async ($, e) => {
    const init = e.init ?? {}
    const call: Call = { method: init.method ?? 'GET', url: e.url, auth: init.headers?.authorization, body: init.body ? JSON.parse(init.body) : undefined }
    w.calls.push(call)
    const reply = (status: number, text: string) => ({ value: { status, ok: status < 300, headers: {}, text } })
    if (e.url.startsWith('https://api.vercel.com/v3/sandboxes')) {
      if (w.createDelayMs) await new Promise(r => setTimeout(r, w.createDelayMs))
      return reply(w.createStatus, w.createStatus < 300 ? JSON.stringify({ sandbox: SANDBOX, session: { ...SESSION, status: w.sessionStatus }, routes: [] }) : JSON.stringify({ error: { message: 'Forbidden' } }))
    }
    if (/\/v2\/sandboxes\/sessions\/[^/]+\/cmd/.test(e.url)) {
      if (isScript(call)) {
        const [script, , ...args] = call.body!.args!.slice(1)
        if (script!.includes('tar -xzf')) return reply(200, finished('git\n'))
        if (script!.includes('@@changes')) {
          const [, watch, patch] = args
          return reply(200, finished(`@@changes\n${w.porcelain}${patch === '1' ? '@@patch 120\n' : ''}${watch === '1' ? '@@outside\n/usr/local/bin/helper\n@@processes\n77 miner\n' : ''}`))
        }
        if (script!.includes('kept no patch')) return reply(200, finished(w.patch))
        return reply(200, finished())
      }
      return reply(w.cmdStatus, w.cmd)
    }
    if (/\/v2\/sandboxes\/sessions\/[^/]+\/stop/.test(e.url)) return reply(200, JSON.stringify({ session: { ...SESSION, status: 'stopping' } }))
    if (/\/v2\/sandboxes\/sessions\/[^/?]+\?/.test(e.url)) return reply(200, JSON.stringify({ session: { ...SESSION, status: w.getStatus }, routes: [] }))
    return reply(404, '{}')
  })
}

